class Solution {
public:
    long long countGoodSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        long long ans = 0;
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && nums[j] == nums[i]) j++;
            unordered_map<long long,long long> cnt;
            cnt[0] = 1;
            long long m = 0;
            for (int t = i; t < j; t++) {
                m = (m + nums[t]) % k;
                ans += cnt[m];
                cnt[m]++;
            }
            i = j;
        }
        return ans;
    }
};

