class Solution {
    public long countGoodSubarrays(int[] nums, int k) {
        int n = nums.length;
        long ans = 0;
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && nums[j] == nums[i]) j++;
            Map<Long,Long> cnt = new HashMap<>();
            cnt.put(0L, 1L);
            long m = 0;
            for (int t = i; t < j; t++) {
                m = (m + nums[t]) % k;
                ans += cnt.getOrDefault(m, 0L);
                cnt.merge(m, 1L, Long::sum);
            }
            i = j;
        }
        return ans;
    }
}

