from math import gcd
class Solution:
    def countGoodSubarrays(self, nums: List[int], k: int) -> int:
        n, ans, i = len(nums), 0, 0
        while i < n:
            j = i
            while j < n and nums[j] == nums[i]:
                j += 1
            L, v = j - i, nums[i]
            p = k // gcd(v, k)
            q, r = divmod(L, p)
            def c2(x):
                return x * (x - 1) // 2
            ans += p * c2(q) + r * c2(q + 1) + q  # +q: empty prefix hits residue 0
            i = j
        return ans

