var countGoodSubarrays = function(nums, k) {
    const gcd = (a,b) => b ? gcd(b, a % b) : a;
    const c2 = x => x * (x - 1) / 2;
    const n = nums.length; let ans = 0, i = 0;
    while (i < n) {
        let j = i;
        while (j < n && nums[j] === nums[i]) j++;
        const L = j - i, v = BigInt(nums[i]), K = BigInt(k);
        const p = K / gcd(v, K);
        const q = L / Number(p), r = L % Number(p);
        ans += Number(p) * c2(q) + r * c2(q + 1) + q;
        i = j;
    }
    return ans;
};
